class EmojiCatalogEntry {
  const EmojiCatalogEntry(this.value, this.label, this.keywords);

  final String value;
  final String label;
  final String keywords;

  bool matches(String query) {
    if (query.isEmpty) return true;
    final normalized = query.toLowerCase().replaceAll(':', '').trim();
    return value.contains(query) ||
        label.toLowerCase().contains(normalized) ||
        keywords.contains(normalized);
  }
}

